      "type": "string",
      "description": "Order identifier."
    }
  }
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "accountId",
    "catalogItemId",
    "productId",
    "itemTitle",
    "quantity",
    "idempotencyKey",
    "confirmationText"
  ],
  "properties": {
    "accountId": {
      "type": "string",
      "description": "Authenticated account scope."
    },
    "catalogItemId": {
      "type": "string",
      "description": "Catalog item identifier from marketplace discovery."
    },
    "productId": {
      "type": "string",
      "description": "Resolved product identifier for the selected options."
    },
    "itemTitle": {
      "type": "string",
      "description": "Buyer-visible item title snapshot."
    },
    "itemSubtitle": {
      "type": "string",
      "description": "Optional buyer-visible item subtitle snapshot."
    },
    "itemImageUrl": {
      "type": "string",
      "description": "Optional buyer-visible item image URL snapshot."
    },
    "selectedOptions": {
      "type": "array",
      "description": "Selected catalog options.",
      "items": {
        "type": "object",
        "description": "Selected catalog option.",
        "additionalProperties": false,
        "required": [
          "dimensionId",
          "optionId"
        ],
        "properties": {
          "dimensionId": {
            "type": "string",
            "description": "Catalog dimension identifier."
          },
          "optionId": {
            "type": "string",
            "description": "Catalog option identifier."
          }
        }
      }
    },
    "productSummary": {
      "type": "string",
      "description": "Optional buyer-visible product summary."
    },
    "quantity": {
      "type": "integer",
      "description": "Requested quantity."
    },
    "fulfillmentMode": {
      "type": "string",
      "description": "Cart fulfillment mode.",
      "enum": [
        "optimize",
        "locked-listing"
      ]
    },
    "lockedListingId": {
      "type": "string",
      "description": "Marketplace listing identifier when locking the line to a seller."
    },
    "sellerPreferenceId": {
      "type": "string",
      "description": "Optional preferred seller account identifier."
    },
    "selectedListingSnapshot": {
      "type": "object",
      "description": "Optional selected listing snapshot for locked-listing lines.",
      "additionalProperties": false,
      "properties": {
        "listingId": {
          "type": "string",
          "description": "Marketplace listing identifier."
        },
        "sellerAccountId": {
          "type": "string",
          "description": "Seller account identifier."
        },
        "sellerDisplayName": {
          "type": "string",
          "description": "Seller display name."
        },
        "sellerSlug": {
          "type": "string",
          "description": "Seller slug."
        },
        "priceAmount": {
          "type": "string",
          "description": "Listing price amount."
        },
        "priceCurrencyCode": {
          "type": "string",
          "description": "Listing price ISO 4217 currency code."
        },
        "listingStreamVersion": {
          "type": "integer",
          "description": "Listing stream version that authored the price pair."
        },
        "source": {
          "type": "string",
          "description": "Snapshot source."
        }
      }
    },
    "idempotencyKey": {
      "type": "string",
      "description": "Stable unique string supplied by the agent host (for example, a UUID). Retried calls must reuse the same key so the action is applied at most once instead of repeating it."
    },
    "confirmationText": {
      "type": "string",
      "description": "Exact user or policy confirmation text."
    },
    "dryRun": {
      "type": "boolean",
      "description": "Validate without changing cart state."
    }
  }
}

